 8	func TestAuthenticationRequiresDatabase(t *testing.T) {
 9		want := map[string]bool{
10			"token":      true,
11			"oidc":       true,
12			"github":     true,
13			"kubernetes": true,
14			"jwt":        false,
15		}
16	
17		for _, method := range (&AuthenticationMethods{}).AllMethods() {
18			method := method
19			t.Run(method.Name(), func(t *testing.T) {
20				if method.RequiresDatabase != want[method.Name()] {
21					t.Fatalf("%s RequiresDatabase = %t, want %t", method.Name(), method.RequiresDatabase, want[method.Name()])
22				}
23	
24				cfg := AuthenticationConfig{Required: true}
25				if cfg.RequiresDatabase() {
26					t.Fatal("Required without an enabled database-backed method should not require a database")
27				}
28	
29				for _, configuredMethod := range cfg.Methods.AllMethods() {
30					if configuredMethod.Name() != method.Name() {
31						continue
32					}
33	
34					configuredMethod.Enable(t)
35					configuredMethod.SetCleanup(t, AuthenticationCleanupSchedule{
36						Interval:    time.Hour,
37						GracePeriod: time.Minute,
38					})
39				}
40	
41				if got := cfg.RequiresDatabase(); got != want[method.Name()] {
42					t.Fatalf("RequiresDatabase() = %t, want %t", got, want[method.Name()])
43				}
44	
45				if got := cfg.ShouldRunCleanup(); got != want[method.Name()] {
