20	func TestAuthenticationGRPCDoesNotConnectDatabaseForJWT(t *testing.T) {
21		privateKey, err := rsa.GenerateKey(rand.Reader, 2048)
22		if err != nil {
23			t.Fatal(err)
24		}
25	
26		publicKey, err := x509.MarshalPKIXPublicKey(&privateKey.PublicKey)
27		if err != nil {
28			t.Fatal(err)
29		}
30		keyPath := filepath.Join(t.TempDir(), "jwt-public-key.pem")
31		if err := os.WriteFile(keyPath, pem.EncodeToMemory(&pem.Block{
32			Type:  "PUBLIC KEY",
33			Bytes: publicKey,
34		}), 0o600); err != nil {
35			t.Fatal(err)
36		}
37	
38		cfg := &config.Config{
39			Authentication: config.AuthenticationConfig{
40				Required: true,
41				Methods: config.AuthenticationMethods{
42					JWT: config.AuthenticationMethod[config.AuthenticationMethodJWTConfig]{
43						Enabled: true,
44						Method: config.AuthenticationMethodJWTConfig{
45							PublicKeyFile: keyPath,
46						},
47					},
48				},
49			},
50			Database: config.DatabaseConfig{URL: "invalid://database-url"},
51			Storage:  config.StorageConfig{Type: config.LocalStorageType},
52		}
53	
54		register, interceptors, shutdown, err := authenticationGRPC(
55			context.Background(),
56			zaptest.NewLogger(t),
57			cfg,
58			false,
59			false,
60		)
61		assert.NoError(t, err)
62		assert.NotEmpty(t, register)
63		assert.NotEmpty(t, interceptors, "JWT authentication middleware should still be configured")
64		if shutdown != nil {
65			assert.NoError(t, shutdown(context.Background()))
66		}
67	}
