69	func TestNewGRPCServer(t *testing.T) {
70		tmp := t.TempDir()
71		cfg := &config.Config{}
72		cfg.Database.URL = fmt.Sprintf("file:%s", filepath.Join(tmp, "flipt.db"))
73		ctx, cancel := context.WithCancel(context.Background())
74		t.Cleanup(cancel)
75		s, err := NewGRPCServer(ctx, zaptest.NewLogger(t), cfg, info.Flipt{}, false)
76		assert.NoError(t, err)
77		t.Cleanup(func() {
78			err := s.Shutdown(ctx)
79			assert.NoError(t, err)
80		})
81		assert.NotEmpty(t, s.Server.GetServiceInfo())
82	}
